import re
RET='docs/mimi-ingredient-bootstrap-checklist-RETURNED-2026-08-24.md'
PRF='/private/tmp/claude-501/-Users-stayman-Personal-projects-my-hermes-agent/82ba9cfd-f3e5-4b9d-b44e-bda24033cd3c/scratchpad/prefs-verify.md'
people=['Stayman','Peggy','Dave','Dennis']

# 1. every marking in the RETURNED checklist
marks={p:[] for p in people}
for L in open(RET):
    if not L.startswith('|'): continue
    c=[x.strip() for x in L.rstrip('\n').strip().strip('|').split('|')]
    if len(c)!=5 or set(c[0])<=set('-: ') or c[0] in ('Ingredient','Ingredient / trait'): continue
    for pers,v in zip(people,c[1:]):
        if v: marks[pers].append((c[0],v))
total=sum(len(v) for v in marks.values())

# 2. per-person section bodies from the prefs file
txt=open(PRF).read()
secs={}
for p in people:
    m=re.search(rf'^## {p}\b.*?(?=^## |\Z)', txt, re.M|re.S)
    secs[p]=m.group(0) if m else ''

def keyword(ing):
    # first meaningful token, lowercased — robust to the qualifier prose
    base=re.split(r'[—/(]', ing)[0].strip().lower()
    for w in base.split():
        if len(w)>3: return w
    return base

print("=== DIRECTION 1: every returned marking appears in 01_Preferences.md ===")
missing=[]
for pers in people:
    for ing,raw in marks[pers]:
        k=keyword(ing)
        if k and k not in secs[pers].lower():
            missing.append((pers,ing,raw,k))
print(f"     returned markings: {total}   traced: {total-len(missing)}   MISSING: {len(missing)}")
for pers,ing,raw,k in missing: print(f"     ⚠️ {pers}: {ing!r} ({raw[:40]!r}) — keyword {k!r} not found")

print()
print("=== DIRECTION 2: every prefs bullet traces back to a returned marking ===")
orphans=[]
for pers in people:
    for line in secs[pers].split('\n'):
        m=re.match(r'^- \*{0,2}(.+?)\*{0,2}(?: —|$)', line.strip())
        if not line.strip().startswith('- '): continue
        item=re.sub(r'\*','',line.strip()[2:]).split('—')[0].strip()
        if not item: continue
        k=keyword(item)
        hit=any(k in keyword(ing) or keyword(ing) in k or k in ing.lower() for ing,_ in marks[pers])
        if not hit: orphans.append((pers,item,k))
print(f"     prefs bullets checked; ORPHANS (no returned marking): {len(orphans)}")
for pers,item,k in orphans: print(f"     ⚠️ {pers}: {item[:60]!r} (keyword {k!r})")
